      this.componentCheck = 1;
      this.editformFields = true;
      this.fieldsData = formfieldsArry;
      this.stepName = Step;
      this.stepIndex = index;
    },
    save_updated_changes(value, name, index) {
      if (name == "Start") {
        this.formElements.forEach(element => {
          value.forEach(element2 => {
            if (element.display_label == element2.label) {
              element.is_displayed = element2.visible;
              element.is_editable = element2.editable;
              element.is_required = element2.mandatory;
            }
          });
        });
        // this.formElements = this.zeroStepInfo;
      } else if (name == this.stepName && index == this.stepIndex) {
        for (var j = 0; j < this.currentSelectedFlow[index].formDetails.length; j++) {
          for (var k = 0; k < value.length; k++) {
            if (this.currentSelectedFlow[index].formDetails[j].display_label == value[k].label) {
              this.currentSelectedFlow[index].formDetails[j].is_displayed = value[k].visible;
              this.currentSelectedFlow[index].formDetails[j].is_editable = value[k].editable;
              this.currentSelectedFlow[index].formDetails[j].is_required = value[k].mandatory;
            }
          }
        }
      }
      this.editformFields = false;
    }
